        boolean codeMatch=!normalize(reqCode).isEmpty()&&normalize(reqCode).equals(normalize(authCode));boolean nameMatch=!normalize(reqName).isEmpty()&&normalize(reqName).equals(normalize(authName));
        if(ocr!=null){if(!Json.str(ocr.get("studentCode")).isEmpty()&&!normalize(Json.str(ocr.get("studentCode"))).equals(normalize(authCode)))codeMatch=false;if(!Json.str(ocr.get("studentName")).isEmpty()&&!normalize(Json.str(ocr.get("studentName"))).equals(normalize(authName)))nameMatch=false;}
        discrepancies.add(UserService.map("field","Định danh chủ sở hữu (MSSV & Họ tên)","studentClaim",reqName+" ("+reqCode+")","institutionalFact",authName+" ("+authCode+")","match",codeMatch&&nameMatch,"note",codeMatch&&nameMatch?"Đúng định danh sinh viên sở hữu tài khoản":"MSSV hoặc họ tên trên yêu cầu không khớp với hồ sơ gốc của sinh viên"));
