        List<String> absent=new ArrayList<String>();if(house.isEmpty()||missing.contains("houseNumber"))absent.add("Số nhà");if(street.isEmpty()||missing.contains("street"))absent.add("Đường/Thôn/Ấp");if(ward.isEmpty()||missing.contains("ward")||missing.contains("wardCommune"))absent.add("Phường/Xã");if(province.isEmpty()||missing.contains("province")||missing.contains("provinceCity"))absent.add("Tỉnh/Thành phố");if(rawAddress.trim().length()<5)absent.add("Địa chỉ thường trú quá ngắn hoặc để trống");
        discrepancies.add(UserService.map("field","Tính đầy đủ của địa chỉ thường trú","studentClaim",rawAddress,"aiFact","Normalized: "+normalized+" | Missing: "+(absent.isEmpty()?"Đầy đủ":String.join(", ",absent)),"match",absent.isEmpty()&&confidence>=threshold,"note",absent.isEmpty()?"Địa chỉ đầy đủ các cấp đơn vị hành chính":"Thiếu thông tin: "+String.join(", ",absent)));
        if(!absent.isEmpty()||confidence<threshold){String msg=!absent.isEmpty()?"Địa chỉ thường trú sinh viên khai báo thiếu dữ kiện bắt buộc ("+String.join(", ",absent)+").":"Độ tin cậy bóc tách địa chỉ thấp hơn ngưỡng quy định.";return verdict("FACT_UNKNOWN","RULE_FACT_01_INCOMPLETE_ADDRESS","Cần cán bộ kiểm tra: "+msg,discrepancies,confidence,threshold,normalized,absent,"Yêu cầu sinh viên bổ sung rõ số nhà, tên đường, phường/xã và tỉnh/thành phố",trust);}
