        String provider=first(Json.str(ctx.get("provider")),Json.str(meta.get("provider")),"");boolean safeLive=live&&!fallback&&!synthetic&&"live".equals(mode);boolean fixture="DETERMINISTIC_TEST".equals(eval.get("evaluationMode"))&&Json.bool(eval.get("allowSyntheticAIAnalysis"))&&"fixture".equals(mode)&&!live&&!fallback&&synthetic&&"FIXED_TEST_FIXTURE".equals(provider);
